// Dumps the size of every loc's model, per shape, for the map-editing tools' size matching
// (server/plugins/agent/data/loc-sizes.json; find_similar_locs, capture_style).
//
//   cd client && npx tsx scripts/cache/dump-loc-sizes.ts [out.json]
//
// Sizes are in model units, 128 to a tile, after the loc's own resize (modelSizeX/Height/Y):
// width along x, depth along y (the map's north-south), height up from the lowest vertex, and
// top, how far above the ground the model reaches. Same cache in, same file out: entries are
// sorted and only measured values are written.
import fs from "node:fs";
import path from "node:path";

import { CacheSystem } from "../../rs/cache/CacheSystem";
import { getCacheLoaderFactory } from "../../rs/cache/loader/CacheLoaderFactory";
import { LocModelLoader } from "../../rs/config/loctype/LocModelLoader";
import { LocModelType } from "../../rs/config/loctype/LocModelType";
import { loadCache, loadCacheInfos, loadCacheList } from "./load-util";

const out = process.argv[2]
    ?? path.resolve(__dirname, "../../../server/plugins/agent/data/loc-sizes.json");

const info = loadCacheList(loadCacheInfos()).latest;
const cache = loadCache(info);
const factory = getCacheLoaderFactory(info, CacheSystem.fromFiles(info, cache.files));
const locTypeLoader = factory.getLocTypeLoader();
const locModelLoader = new LocModelLoader(locTypeLoader, factory.getModelLoader(), factory.getTextureLoader(),
    factory.getSeqTypeLoader(), factory.getSeqFrameLoader(), factory.getSkeletalSeqLoader());

const lines: string[] = [];
let measured = 0;
const count = locTypeLoader.getCount();
for (let id = 0; id < count; id++) {
    let locType;
    try {
        locType = locTypeLoader.load(id);
    } catch {
        continue;
    }
    if (!locType?.models || locType.models.length === 0) continue;
    // A loc with per-shape models has one per type; one without has a single model, used as
    // scenery (shape 10).
    const shapes: number[] = locType.types ? [...new Set(locType.types as number[])].sort((a, b) => a - b) : [LocModelType.NORMAL];
    const sizes: number[][] = [];
    for (const shape of shapes) {
        let model;
        try {
            model = locModelLoader.getLocModelData(locType, shape, 0);
        } catch {
            continue;
        }
        if (!model || model.verticesCount === 0) continue;
        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity, minZ = Infinity, maxZ = -Infinity;
        for (let v = 0; v < model.verticesCount; v++) {
            const x = model.verticesX[v], y = model.verticesY[v], z = model.verticesZ[v];
            if (x < minX) minX = x; if (x > maxX) maxX = x;
            if (y < minY) minY = y; if (y > maxY) maxY = y;
            if (z < minZ) minZ = z; if (z > maxZ) maxZ = z;
        }
        // Model y grows downwards; the ground is y = 0.
        const sx = locType.modelSizeX / 128, sh = locType.modelSizeHeight / 128, sy = locType.modelSizeY / 128;
        sizes.push([
            shape,
            Math.round((maxX - minX) * sx),
            Math.round((maxZ - minZ) * sy),
            Math.round((maxY - minY) * sh),
            Math.round(-minY * sh),
        ]);
    }
    if (sizes.length === 0) continue;
    measured++;
    lines.push(`  ${JSON.stringify(String(id))}: ${JSON.stringify(sizes)}`);
}

const header = {
    about: "Loc model sizes per shape: [shape, width, depth, height, top] in model units (128 = one tile), "
        + "after the loc's resize. Generated by client/scripts/cache/dump-loc-sizes.ts; do not edit by hand.",
    revision: info.revision,
};
fs.writeFileSync(out, `{\n  "about": ${JSON.stringify(header.about)},\n  "revision": ${header.revision},\n  "locs": {\n${lines.map((l) => `  ${l}`).join(",\n")}\n  }\n}\n`);
console.log(`measured ${measured} of ${count} locs -> ${out}`);
